import styles from './app.module.css'
import { useEffect, useState } from 'react';
import Video_list from './components/video_list/video_list';
import Search_header from './components/search_header/search_header';
import Video_detail from './components/video_detail/video_detail';

function App({ youtube }) {
  const [videos, setVideos] = useState([]);
  const [selectedVideo, setSelectedVideo] = useState(null);

  const selectVideo = (video) => {
    setSelectedVideo(video)
  }
  const search = query => {
    youtube.search(query)
      .then(videos => setVideos(videos))

    fetch(`https://www.googleapis.com/youtube/v3/search?part=snippet&maxResults=100&q=${query}&key=AIzaSyALd5gN0lZ5gFbk7dys3373SqkmhNcF_dE`,
      requestOptions)
      .then(response => response.json())
      .then(result => setVideos(result.items))
      .catch(error => console.log('error', error));
  };

  useEffect(() => {
    youtube.mostPopuler()
      .then(videos => setVideos(videos));
    setSelectedVideo(null)

    fetch("https://youtube.googleapis.com/youtube/v3/search?part=snippet&maxResults=100&q=cat&key=AIzaSyALd5gN0lZ5gFbk7dys3373SqkmhNcF_dE", requestOptions)
      .then(response => response.json())
      .then(result => setVideos(result.items))
      .catch(error => console.log('error', error));
  }, [])

  return <>
    <Search_header onSearch={search} />
    <section className={styles.content}>
      {selectedVideo && (<div className={styles.detail}>
        <Video_detail video={selectedVideo} />
      </div>)}
      <div className={styles.list}>
        <Video_list videos={videos} onVideoClick={selectVideo} display={selectedVideo ? 'list' : 'grid'}></Video_list>
      </div>
    </section>

  </>
}

export default App;
